END_VAR
```

### 现场手动参数

```iecst
VAR_GLOBAL CONSTANT

    AXIS_COUNT : INT := 5;

    // ================= MANUAL PARAMETER =================
    // 每个轴：PLC 用户单位对应的实际机械角度/位移。
    // 必须根据编码器分辨率、电子齿轮和减速比重新确认。
    AxisScale : ARRAY[1..5] OF LREAL := [
        72.0,              // X：示例值，减速比 5
        13.846153846,      // Y：示例值，必须现场确认
        72.0,              // Z：示例值，必须现场确认
        1.0,               // B：必须现场确认
        1.0                // C：必须现场确认
    ];

    // ================= MANUAL PARAMETER =================
    AxisMinPosition : ARRAY[1..5] OF LREAL :=
        [-360.0, -360.0, -360.0, -360.0, -360.0];

    AxisMaxPosition : ARRAY[1..5] OF LREAL :=
        [ 360.0,  360.0,  360.0,  360.0,  360.0];

    // ================= MANUAL PARAMETER =================
    AxisMaxVelocity : ARRAY[1..5] OF LREAL :=
        [100.0, 100.0, 100.0, 100.0, 100.0];

    // ================= MANUAL PARAMETER =================
    AxisAcceleration : ARRAY[1..5] OF LREAL :=
        [17000.0, 10000.0, 9000.0, 100.0, 100.0];

    // ================= MANUAL PARAMETER =================
    AxisDeceleration : ARRAY[1..5] OF LREAL :=
        [17000.0, 10000.0, 9000.0, 100.0, 100.0];

    // ================= MANUAL PARAMETER =================
    MODBUS_PORT : UINT := 502;
