### 单轴控制功能块

```iecst
FUNCTION_BLOCK FB_AxisChannel
VAR_IN_OUT
    Axis : AXIS_REF_SM3;
END_VAR

VAR_INPUT
    EnableRequest : BOOL;
    StartMove     : BOOL;
    Target        : LREAL;
    Velocity      : LREAL;
    Acceleration  : LREAL;
    Deceleration  : LREAL;
    ResetRequest  : BOOL;
END_VAR

VAR_OUTPUT
    Enabled       : BOOL;
    Actual        : LREAL;
    Busy          : BOOL;
    Done          : BOOL;
    Error         : BOOL;
    ErrorID       : SMC_ERROR;
    Disabled      : BOOL;
    ErrorStop     : BOOL;
    SoftwareLimit : BOOL;
END_VAR

VAR
    fbPower    : MC_Power;
    fbMove     : MC_MoveAbsolute;
    fbPosition : MC_ReadActualPosition;
    fbStatus   : MC_ReadStatus;
    fbReset    : MC_Reset;

    moveEdge  : R_TRIG;
    resetEdge : R_TRIG;
    movePulse : BOOL;
END_VAR


// 读取实际位置
fbPosition(
    Axis := Axis,
    Enable := TRUE,
    Position => Actual
);

// 读取轴状态
fbStatus(
    Axis := Axis,
    Enable := TRUE,
    Disabled => Disabled,
    Errorstop => ErrorStop
);

// 伺服使能
fbPower(
    Axis := Axis,
    Enable := TRUE,
    bRegulatorOn := EnableRequest,
    bDriveStart := EnableRequest,
    Status => Enabled,
    Error => Error,
    ErrorID => ErrorID
);

// 故障复位只允许上升沿触发
resetEdge(CLK := ResetRequest);

fbReset(
    Axis := Axis,
    Execute := resetEdge.Q
);

// 运动命令只接受一次上升沿
moveEdge(CLK := StartMove);

IF moveEdge.Q AND EnableRequest AND NOT Error THEN
    movePulse := TRUE;
    Done := FALSE;
END_IF;

// 绝对定位
fbMove(
    Axis := Axis,
    Execute := movePulse,
    Position := Target,
    Velocity := Velocity,
    Acceleration := Acceleration,
    Deceleration := Deceleration,
    Done => Done,
    Busy => Busy,
    Error => Error,
    ErrorID => ErrorID
);

// Execute 只保持一个 PLC 周期
movePulse := FALSE;
```

### 五轴流程程序

```iecst
PROGRAM PRG_FiveAxisSequence
VAR
    i : INT;

    moveEdge : R_TRIG;
    fbAxis   : ARRAY[1..5] OF FB_AxisChannel;

    axisEnabled : ARRAY[1..5] OF BOOL;
    axisDone    : ARRAY[1..5] OF BOOL;
    axisBusy    : ARRAY[1..5] OF BOOL;
    axisError   : ARRAY[1..5] OF BOOL;
    axisErrorID : ARRAY[1..5] OF SMC_ERROR;

    allEnabled : BOOL;
    allDone    : BOOL;
    anyError   : BOOL;
    targetTemp : LREAL;
END_VAR


// 这里必须绑定设备树中的真实轴
fbAxis[1](
    Axis := AXIS_X,
    EnableRequest := AxisEnableRequest,
    StartMove := MoveRequest,
    Target := AxisTarget[1],
    Velocity := AxisMaxVelocity[1],
    Acceleration := AxisAcceleration[1],
    Deceleration := AxisDeceleration[1],
    Enabled => axisEnabled[1],
    Actual => AxisActual[1],
    Busy => axisBusy[1],
    Done => axisDone[1],
    Error => axisError[1],
    ErrorID => axisErrorID[1]
);

fbAxis[2](
    Axis := AXIS_Y,
    EnableRequest := AxisEnableRequest,
    StartMove := MoveRequest,
    Target := AxisTarget[2],
    Velocity := AxisMaxVelocity[2],
    Acceleration := AxisAcceleration[2],
    Deceleration := AxisDeceleration[2],
    Enabled => axisEnabled[2],
    Actual => AxisActual[2],
    Busy => axisBusy[2],
    Done => axisDone[2],
    Error => axisError[2],
    ErrorID => axisErrorID[2]
);

fbAxis[3](
    Axis := AXIS_Z,
    EnableRequest := AxisEnableRequest,
    StartMove := MoveRequest,
    Target := AxisTarget[3],
    Velocity := AxisMaxVelocity[3],
    Acceleration := AxisAcceleration[3],
    Deceleration := AxisDeceleration[3],
    Enabled => axisEnabled[3],
    Actual => AxisActual[3],
    Busy => axisBusy[3],
    Done => axisDone[3],
    Error => axisError[3],
    ErrorID => axisErrorID[3]
);

fbAxis[4](
    Axis := AXIS_B,
    EnableRequest := AxisEnableRequest,
    StartMove := MoveRequest,
    Target := AxisTarget[4],
    Velocity := AxisMaxVelocity[4],
    Acceleration := AxisAcceleration[4],
    Deceleration := AxisDeceleration[4],
    Enabled => axisEnabled[4],
    Actual => AxisActual[4],
    Busy => axisBusy[4],
    Done => axisDone[4],
    Error => axisError[4],
    ErrorID => axisErrorID[4]
);

fbAxis[5](
    Axis := AXIS_C,
    EnableRequest := AxisEnableRequest,
    StartMove := MoveRequest,
    Target := AxisTarget[5],
    Velocity := AxisMaxVelocity[5],
    Acceleration := AxisAcceleration[5],
    Deceleration := AxisDeceleration[5],
    Enabled => axisEnabled[5],
    Actual => AxisActual[5],
    Busy => axisBusy[5],
    Done => axisDone[5],
    Error => axisError[5],
    ErrorID => axisErrorID[5]
);


// 汇总状态
allEnabled := TRUE;
allDone := TRUE;
anyError := FALSE;

FOR i := 1 TO AXIS_COUNT DO
    IF NOT axisEnabled[i] THEN
        allEnabled := FALSE;
    END_IF;

    IF NOT axisDone[i] THEN
        allDone := FALSE;
    END_IF;

    IF axisError[i] THEN
        anyError := TRUE;
        SequenceErrorID := TO_DWORD(axisErrorID[i]);
    END_IF;
END_FOR;


// 线圈 2：五轴运动请求，上升沿有效
moveEdge(CLK := arDo_data[2]);

IF moveEdge.Q
   AND (SequenceState = 0)
   AND allEnabled
   AND NOT anyError THEN

    FOR i := 1 TO AXIS_COUNT DO

        // 保持寄存器 0..4：目标值，单位为 0.1 用户单位
        targetTemp := WORD_TO_INT(arReg_data[i - 1]);
        IF targetTemp >= 32768.0 THEN
            targetTemp := targetTemp - 65536.0;
        END_IF;

        AxisTarget[i] :=
            targetTemp * 0.1 * AxisScale[i];

        IF AxisTarget[i] < AxisMinPosition[i] THEN
            AxisTarget[i] := AxisMinPosition[i];
        END_IF;

        IF AxisTarget[i] > AxisMaxPosition[i] THEN
            AxisTarget[i] := AxisMaxPosition[i];
        END_IF;
    END_FOR;

    AxisEnableRequest := arDo_data[0];
    MoveRequest := TRUE;
    SequenceError := FALSE;
    SequenceState := 10;
END_IF;


// 运动执行中
IF SequenceState = 10 THEN

    IF anyError THEN
        MoveRequest := FALSE;
        SequenceError := TRUE;
        SequenceState := 30;

    ELSIF allDone THEN
        MoveRequest := FALSE;
        SequenceState := 20;
    END_IF;
END_IF;


// 输入寄存器反馈
arAi_data[0] := INT_TO_WORD(SequenceState);

FOR i := 1 TO AXIS_COUNT DO
    // 输入寄存器 1..5：实际位置，单位 0.1 用户单位
    arAi_data[i] := LREAL_TO_WORD(AxisActual[i] * 10.0);
END_FOR;
```

### Modbus TCP 从站

```iecst
PROGRAM PRG_ModbusTcpSlave
VAR
    fbInit : GCAN.FB_ModbusTCP_Slave_Init;
    fbCtrl : GCAN.FB_ModbusTCP_Slave_Ctrl;

    socket : INT;
    clients : ARRAY[0..10] OF INT;

    initDone : BOOL := FALSE;
    ctrlEnable : BOOL := FALSE;
    modbusError : UINT;
END_VAR


IF NOT initDone THEN

    fbInit(
        en_in := TRUE,
        xEnable := TRUE,
        iPort := MODBUS_PORT,
        iSocket => socket,
        uiError => modbusError
    );

    IF (socket >= 0) AND (modbusError = 0) THEN
        initDone := TRUE;
    END_IF;

ELSE

    fbCtrl(
        en_in := ctrlEnable,
        xEnable := TRUE,
        iSocket := socket,
        pClientSocket := ADR(clients),
        iMaxClientCount := 10,

        // 线圈 0..3
        uiDoNumber := 4,
        uiDoStartAddr := 0,
        pDoData := ADR(arDo_data),

        // 离散输入 0..15
        uiDiNumber := 16,
        uiDiStartAddr := 0,
        pDiData := ADR(arDi_data),

        // 保持寄存器 0..199
        uiRegNumber := 200,
        uiRegStartAddr := 0,
        pRegData := ADR(arReg_data),

        // 输入寄存器 0..5
        uiAiNumber := 6,
        uiAiStartAddr := 0,
        pAiData := ADR(arAi_data),

        dWatchdogTime :=
